// Read every project file at once, then analyze in JS.
const files = [
  'src/lib/log.js',
  'src/api/health.js',
  'src/api/orders.js',
  'src/api/users.js',
  'src/auth/session.js',
  'src/auth/tokens.js',
  'src/index.js',
  'src/jobs/cleanup.js',
  'src/jobs/report.js',
  'src/jobs/sync.js',
  'src/lib/config.js',
  'src/util/legacyLogger.js',
  'src/util/retry.js',
  'src/util/strings.js',
];
const reads = await Promise.allSettled(files.map(f => tools.read({ path: f, offset: 1, limit: 500 })));
const contents = {};
files.forEach((f, i) => {
  contents[f] = reads[i].status === 'fulfilled' ? String(reads[i].value) : null;
});

// 1+2: find legacyLog( call sites and the enclosing function
function enclosingName(lines, idx) {
  let depth = 0;
  for (let i = idx; i >= 0; i--) {
    const line = lines[i];
    // count braces on each line as we walk upward
    for (let j = line.length - 1; j >= 0; j--) {
      if (i === idx && j > line.indexOf('legacyLog(') + 9 && depth === 0 && idx !== i) continue;
      const c = line[j];
      if (c === '}' || c === ')') depth++;
      else if (c === '{' || c === '(') depth--;
    }
    if (depth < 0) {
      // this line opens the enclosing block; extract its name
      const m = line.match(/(?:async\s+)?(?:function\s*\*?\s*([A-Za-z_$][\w$]*)|(?:get|set|static|async)\s+([A-Za-z_$][\w$]*)\s*\(|([A-Za-z_$][\w$]*)\s*\([^)]*\)\s*\{|([A-Za-z_$][\w$]*)\s*[:=]\s*(?:async\s*)?(?:function|\([^)]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>))/);
      return m ? (m[1] || m[2] || m[3] || m[4]) : line.trim();
    }
  }
  return '(top-level)';
}

const callSites = [];
for (const f of files) {
  const text = contents[f];
  if (!text) { console.log('!! could not read ' + f); continue; }
  const lines = text.split('\n');
  lines.forEach((line, i) => {
    let col = line.indexOf('legacyLog(');
    while (col !== -1) {
      // skip comments and the definition/export lines
      const before = line.slice(0, col).trim();
      if (!/^\*|^\/\/|^\/\*|^export\s/.test(before)) {
        callSites.push({ file: f, line: i + 1, col, name: enclosingName(lines, i), lineText: line.trim() });
      }
      col = line.indexOf('legacyLog(', col + 1);
    }
  });
}

console.log('=== legacyLog call sites ===');
for (const c of callSites) console.log(`${c.file}:${c.line} in <${c.name}> :: ${c.lineText}`);
console.log('total call sites: ' + callSites.length);

// 3: config keys vs usage in source
const appCfg = JSON.parse(await tools.read({ path: 'config/app.json', offset: 1, limit: 200 }));
const jobsCfg = JSON.parse(await tools.read({ path: 'config/jobs.json', offset: 1, limit: 200 }));
const flat = (obj, prefix) => Object.entries(obj).flatMap(([k, v]) =>
  typeof v === 'object' && v !== null && !Array.isArray(v) ? flat(v, prefix ? prefix + '.' + k : k) : [prefix ? prefix + '.' + k : k]);
const keys = [...flat(appCfg, '').map(k => 'app.json:' + k), ...flat(jobsCfg, '').map(k => 'jobs.json:' + k)];
const srcAll = Object.values(contents).filter(Boolean).join('\n');
console.log('=== config key usage ===');
for (const k of keys) {
  const bare = k.split(':').slice(1).join(':');
  const last = bare.split('.').pop();
  console.log(`${k} -> used: ${srcAll.includes("'" + bare + "'") || srcAll.includes('"' + bare + '"') || srcAll.includes("'" + last + "'") || srcAll.includes('"' + last + '"')}`);
}

// also print config.js and index.js so I can verify how keys are loaded
console.log('=== src/lib/config.js ===\n' + contents['src/lib/config.js']);
console.log('=== src/index.js ===\n' + contents['src/index.js']);
return 'done';

const files = ['src/api/users.js','src/api/orders.js','src/auth/session.js','src/auth/tokens.js','src/jobs/cleanup.js','src/jobs/report.js','src/util/retry.js','src/util/legacyLogger.js','src/lib/log.js','src/jobs/sync.js','src/api/health.js','src/util/strings.js'];
const reads = await Promise.all(files.map(f => tools.read({ path: f, offset: 1, limit: 300 })));
files.forEach((f, i) => console.log(`===== ${f} =====\n${reads[i].value}\n`));
// exhaustive raw grep for legacyLog and for archiveAfterDays / every key across ALL files
const all = files.map((f,i)=>({f, t:String(reads[i].value)}));
for (const {f, t} of all) {
  const hits = t.split('\n').map((l,i)=>[i+1,l]).filter(([n,l])=>l.includes('legacyLog'));
  if (hits.length) console.log('legacyLog in ' + f + ' -> lines: ' + hits.map(h=>h[0]).join(','));
}
console.log('archiveAfterDays anywhere:', all.some(({t})=>t.includes('archiveAfterDays')));
return 'ok';

const files = ['src/api/users.js','src/api/orders.js','src/auth/session.js','src/auth/tokens.js','src/jobs/cleanup.js','src/jobs/report.js','src/util/retry.js','src/util/legacyLogger.js','src/lib/log.js','src/jobs/sync.js','src/api/health.js','src/util/strings.js'];
const reads = await Promise.all(files.map(f => tools.read({ path: f, offset: 1, limit: 300 })));
files.forEach((f, i) => console.log(`===== ${f} =====\n${String(reads[i])}\n`));
for (let i = 0; i < files.length; i++) {
  const lines = String(reads[i]).split('\n');
  const hits = lines.map((l, n) => [n + 1, l]).filter(([, l]) => l.includes('legacyLog'));
  if (hits.length) console.log('legacyLog in ' + files[i] + ' -> lines: ' + hits.map(h => h[0]).join(','));
}
console.log('archiveAfterDays anywhere:', files.some((f, i) => String(reads[i]).includes('archiveAfterDays')));
return 'ok';
